macro_rules! align_down_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function align_down in module {}", module_path!());
    };
}

mkfn!{
    align_down_introspect!();
    # [inline (always)] fn align_down (val : usize , align : usize) -> usize { debug_assert ! (align . is_power_of_two ()) ; val & ! (align - 1) }
}

macro_rules! align_up_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function align_up in module {}", module_path!());
    };
}

mkfn!{
    align_up_introspect!();
    # [inline (always)] fn align_up (val : usize , align : usize) -> usize { debug_assert ! (align . is_power_of_two ()) ; (val + align - 1) & ! (align - 1) }
}
mkitem!{const DROPLESS_ALIGNMENT : usize = align_of :: < usize > () ;}
mkitem!{mkstruct!{# [doc = " An arena that can hold objects of multiple different types that impl `Copy`"] # [doc = " and/or satisfy `!mem::needs_drop`."] pub struct DroplessArena { # [doc = " A pointer to the start of the free space."] start : Cell < * mut u8 > , # [doc = " A pointer to the end of free space."] # [doc = ""] # [doc = " The allocation proceeds downwards from the end of the chunk towards the"] # [doc = " start. (This is slightly simpler and faster than allocating upwards,"] # [doc = " see <https://fitzgeraldnick.com/2019/11/01/always-bump-downwards.html>.)"] # [doc = " When this pointer crosses the start pointer, a new chunk is allocated."] # [doc = ""] # [doc = " This is kept aligned to DROPLESS_ALIGNMENT."] end : Cell < * mut u8 > , # [doc = " A vector of arena chunks."] chunks : RefCell < Vec < ArenaChunk > > , }}}
